// 精确cursor读同一原成本尺；技术切片不重跑选路、partial_point或取整。
#include "movement_exact_detail.hpp"
#include <algorithm>
#include <cmath>
#include <cstring>
#include <limits>
#if defined(__clang__)
#pragma clang fp contract(off)
#pragma clang fp reassociate(off)
#elif defined(__GNUC__)
#pragma GCC optimize ("no-fast-math", "fp-contract=off")
#endif
namespace hanmo::resident {
using namespace movement_detail;
// 持久binary64用固定16小写十六进制；-0正规化，不接受NaN或无穷。
Outcome<StableId> encode_movement_binary64(double value){return guard<StableId>([&]{if(!std::isfinite(value))fail("NonFiniteMovementAnchor");if(value==0)value=0;std::uint64_t bits=0;std::memcpy(&bits,&value,8);StableId out(16,'0');constexpr char hex[]="0123456789abcdef";for(unsigned i=0;i<16;++i)out[15-i]=hex[(bits>>(4*i))&15];return out;});}
// 冷读拒绝非规范负零，不能借修正读档改变真实源位模式。
Outcome<double> decode_movement_binary64(const StableId& value){return guard<double>([&]{if(value.size()!=16)fail("InvalidMovementBinary64");std::uint64_t bits=0;for(char c:value){unsigned n=c>='0'&&c<='9'?unsigned(c-'0'):c>='a'&&c<='f'?unsigned(c-'a'+10):16;if(n==16)fail("InvalidMovementBinary64");bits=(bits<<4)|n;}if(bits==(std::uint64_t(1)<<63))fail("NonCanonicalMovementZero");double out=0;std::memcpy(&out,&bits,8);if(!std::isfinite(out))fail("NonFiniteMovementAnchor");return out;});}
// 几何生产时的三分支逐一消费，unused tail从来不是实际已耗成本。
Outcome<CanonicalFraction> movement_consumed_cost(const TerrainCostBasis& basis,const CanonicalFraction& cursor,ExactArithmeticBudget budget){return guard<CanonicalFraction>([&]{if(compare(cursor,basis.parameter_limit.value,budget)>0)fail("MovementCursorOutsideBasis",basis.basis_ref);CanonicalFraction total;for(const auto& p:basis.pieces){if(p.kind==TerrainCostPieceKind::unused_budget_tail)continue;auto lo=p.cost_from;auto hi=p.cost_to;if(compare(cursor,lo,budget)<=0)continue;auto stop=compare(cursor,hi,budget)<0?cursor:hi;total=add(total,sub(stop,lo,budget),budget);}return total;});}
// 旧原整数算法直接提供pieces/consumed/reached，不从显示终点或end_credit反推。
Outcome<TerrainCostBasis> make_original_terrain_cost_basis(const TravelMotion& trace,const StableId& id,const StableId& rule,const StableId& unit,const SourceRef& source,ExactArithmeticBudget budget){return guard<TerrainCostBasis>([&]{take(validate_terrain_trace(trace));if(!trace.moving||trace.stationary||id.empty()||rule.empty()||unit.empty()||!source_valid(source)||trace.cost_piece_kinds.size()!=trace.segments.size())fail("MovementGeometryProducerRequired",id);TerrainCostBasis out;out.basis_ref=id;out.original_inputs=trace.params;out.original_inputs.field_order.clear();out.parameter_limit.value=integer(trace.budget,budget);out.actual_consumed_total=trace.actual_consumed_total;out.reached_points=trace.reached_points;out.original_point_count=trace.original_point_count;out.original_end_credit=trace.end_credit;out.original_closing_policy=trace.reached_points==trace.original_point_count?TerrainOriginalClosingPolicy::arrival_discard:TerrainOriginalClosingPolicy::carry_at_unit_boundary;out.catalog_rule_ref=rule;out.original_unit_ref=unit;const auto& first=trace.segments.front().from;if(first.x!=std::floor(first.x)||first.y!=std::floor(first.y))fail("OriginalTerrainIntegerOriginRequired");out.start_anchor=OriginalMovementAnchor{WildernessLocation{trace.map_id,trace.origin,{Integer(first.x),Integer(first.y)}},source};out.end_anchor=OriginalMovementAnchor{WildernessLocation{trace.map_id,trace.origin,trace.end},source};for(std::size_t i=0;i<trace.segments.size();++i)out.pieces.push_back({trace.cost_piece_kinds[i],trace.segments[i],take(fraction_from_binary64(trace.segments[i].start_cost,budget)),take(fraction_from_binary64(trace.segments[i].end_cost,budget))});if(compare(take(movement_consumed_cost(out,out.parameter_limit.value,budget)),integer(out.actual_consumed_total,budget),budget)!=0)fail("MovementCostProducerMismatch",id);return out;});}
// 原道路一单位的夹边结果保真；新分数位置仍按原方向插值。
Outcome<RoadMovementBasis> make_original_road_movement_basis(const RoadTravelMotion& trace,const StableId& id,const StableId& rule,const StableId& unit,const SourceRef& source,ExactArithmeticBudget budget){return guard<RoadMovementBasis>([&]{if(id.empty()||rule.empty()||unit.empty()||!trace.moving||trace.start<0||trace.end<0||trace.action_id.empty()||trace.edge_id.empty()||!source_valid(source))fail("OriginalRoadProducerRequired",id);RoadMovementBasis out;out.basis_ref=id;out.original_inputs=trace;out.original_inputs.params.field_order.clear();out.exact_start_progress=integer(trace.start,budget);out.exact_end_progress=integer(trace.end,budget);out.start_anchor=OriginalMovementAnchor{OnRouteLocation{trace.edge_id,trace.origin,trace.start},source};out.end_anchor=OriginalMovementAnchor{OnRouteLocation{trace.edge_id,trace.origin,trace.end},source};out.catalog_rule_ref=rule;out.original_unit_ref=unit;return out;});}
// 身体位置总是由basis与总cursor导出；Held不另存第二坐标。
Outcome<MovementAnchor> read_movement_position(const MovementPrefixState& state,ExactArithmeticBudget budget){return guard<MovementAnchor>([&]() -> MovementAnchor {if(const auto* c=std::get_if<MovementClosed>(&state.lifecycle))return c->actual_anchor;auto limit=basis_limit(state.basis,budget);if(compare(state.cursor,limit,budget)>0)fail("MovementCursorOutsideBasis",state.id);if(const auto* road=std::get_if<RoadMovementBasis>(&state.basis)){if(compare(state.cursor,CanonicalFraction{},budget)==0)return road->start_anchor;if(compare(state.cursor,limit,budget)==0)return road->end_anchor;const bool forward=compare(road->exact_end_progress,road->exact_start_progress,budget)>=0;auto distance=forward?sub(road->exact_end_progress,road->exact_start_progress,budget):sub(road->exact_start_progress,road->exact_end_progress,budget);auto delta=mul(distance,state.cursor,budget);auto progress=forward?add(road->exact_start_progress,delta,budget):sub(road->exact_start_progress,delta,budget);return RoadFractionalAnchor{road->original_inputs.edge_id,road->original_inputs.origin,std::move(progress),{"travel","movement_prefix",state.id}};}
    const auto& terrain=std::get<TerrainCostBasis>(state.basis);if(compare(state.cursor,CanonicalFraction{},budget)==0)return terrain.start_anchor;if(compare(state.cursor,limit,budget)==0)return terrain.end_anchor;if(terrain.pieces.empty())fail("MovementCostPiecesRequired",state.id);ContactPoint point=terrain.pieces.back().segment.to;
    if(!terrain.continued){const double lambda=take(fraction_to_binary64(div(state.cursor,limit,budget),budget));const double q=take(fraction_to_binary64(limit,budget));for(const auto& piece:terrain.pieces){const auto& p=piece.segment;double start=p.start_cost/q,end=p.end_cost/q;if(lambda>end)continue;double elapsed=std::clamp(lambda,start,end)-start;double vx=(p.to.x-p.from.x)/(end-start),vy=(p.to.y-p.from.y)/(end-start);point={p.from.x+vx*elapsed,p.from.y+vy*elapsed};break;}}
    else for(const auto& piece:terrain.pieces){const auto& p=piece.segment;auto start=piece.cost_from,end=piece.cost_to;if(compare(state.cursor,end,budget)>0)continue;auto clamped=compare(state.cursor,start,budget)<0?start:state.cursor;double lambda=take(fraction_to_binary64(div(sub(clamped,start,budget),sub(end,start,budget),budget),budget));point={p.from.x+(p.to.x-p.from.x)*lambda,p.from.y+(p.to.y-p.from.y)*lambda};break;}
    return TerrainContinuousAnchor{terrain.original_inputs.map_id,terrain.original_inputs.origin,take(encode_movement_binary64(point.x)),take(encode_movement_binary64(point.y)),{"travel","movement_prefix",state.id},terrain.catalog_rule_ref};});}
// 显示兼容仅投影；调用方必须禁止将结果作为新geometry起点。
Outcome<Location> project_movement_location(const MovementAnchor& anchor,ExactArithmeticBudget budget){return guard<Location>([&]() -> Location {if(const auto* p=std::get_if<OriginalMovementAnchor>(&anchor))return p->location;if(const auto* p=std::get_if<RoadFractionalAnchor>(&anchor))return OnRouteLocation{p->edge_id,p->origin,take(floor_fraction(p->progress,budget))};const auto& p=std::get<TerrainContinuousAnchor>(anchor);double x=take(decode_movement_binary64(p.x_bits)),y=take(decode_movement_binary64(p.y_bits));if(x<0||y<0||x>100000||y>100000)fail("MovementAnchorOutsideMap");return WildernessLocation{p.map_id,p.origin,{Integer(std::round(x)),Integer(std::round(y))}};});}
// 原接触比值原样映入世界时间，锚点深值与suffix只复制，不重新采样。
Outcome<ExactMovementContact> map_movement_contact(const StableId& id,const ContactHit& hit,const WorldMoment& from,const HalfDayDuration& duration,const StableId& a,const StableId& b,ExactArithmeticBudget budget){return guard<ExactMovementContact>([&]{if(id.empty()||hit.time_num<0||hit.time_den<=0||hit.time_num>hit.time_den||a.empty()||b.empty()||a==b||compare(duration.value,CanonicalFraction{},budget)<=0)fail("InvalidExactContact");auto fraction=take(normalize_fraction(std::to_string(hit.time_num),std::to_string(hit.time_den),budget));auto at=take(add_world_duration(from,{mul(duration.value,fraction,budget)},budget));return ExactMovementContact{id,hit,from,duration,at,a,b};});}
} // 几何读取不分ID、不扣费、不推进世界或修改知情。

namespace hanmo::resident {using namespace movement_detail;
Outcome<CanonicalFraction> read_exact_contact_fraction(const ExactMovementContact& source,ExactArithmeticBudget b){return guard<CanonicalFraction>([&]{if(source.geometry_profile==ExactContactGeometryProfile::road_rational_v1){if(!source.exact_road_fraction||!source.original_hit.road||source.original_hit.time_num!=0||source.original_hit.time_den!=0||compare(*source.exact_road_fraction,integer(1,b),b)>0)fail("ExactRoadContactRatioMismatch",source.id);return *source.exact_road_fraction;}if(source.exact_road_fraction||(source.geometry_profile!=ExactContactGeometryProfile::original_integer&&source.geometry_profile!=ExactContactGeometryProfile::terrain_local_v1)||(source.geometry_profile==ExactContactGeometryProfile::terrain_local_v1&&source.original_hit.road))fail("ExactContactGeometryProfileMismatch",source.id);const auto& hit=source.original_hit;if(hit.time_num<0||hit.time_den<=0||hit.time_num>hit.time_den)fail("InvalidExactContact",source.id);return take(normalize_fraction(std::to_string(hit.time_num),std::to_string(hit.time_den),b));});}
Outcome<WorldMoment> read_exact_contact_mapped_moment(const ExactMovementContact& source,ExactArithmeticBudget b){return guard<WorldMoment>([&]{if(source.first_prefix_id.empty()||source.second_prefix_id.empty()||source.first_prefix_id==source.second_prefix_id||compare(source.window_duration.value,{},b)<=0)fail("InvalidExactContact",source.id);auto fraction=take(read_exact_contact_fraction(source,b));return take(add_world_duration(source.window_from,{mul(source.window_duration.value,fraction,b)},b));});}
}
